charBubbleCSS:
/* 我方气泡 */
.bubble-me-custom {
  background: #F2F2F2 !important;
  color: #000 !important;
  border: 1px solid #D9D9D9 !important;
  position: relative !important;
  padding: 4px 6px !important;
  font-size: 14px !important;
  z-index: 1 !important;
  margin-top: 4px !important;
}

/* 我方左上角贴纸 */
.bubble-me-custom::before {
  content: "" !important;
  position: absolute !important;
  left: -11px !important;
  top: -11px !important;
  width: 24px !important;
  height: 24px !important;
  background-image: url(https://imgbed.heliar.top/file/1775460496656_retouch_2026040615243515.png) !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  z-index: 9999 !important;
  pointer-events: none !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
}

/* 对方气泡 */
.bubble-them-custom {
  background: #FFFFFF !important;
  color: #000 !important;
  border: 1px solid #E6E6E6 !important;
  position: relative !important;
  padding: 4px 6px !important;
  font-size: 14px !important;
  z-index: 1 !important;
  margin-top: 4px !important;
}

/* 对方右上角贴纸（左右翻转） */
.bubble-them-custom::after {
  content: "" !important;
  position: absolute !important;
  right: -13px !important;
  top: -11px !important;
  width: 24px !important;
  height: 24px !important;
  background-image: url(https://imgbed.heliar.top/file/1775460491566_retouch_2026040615245172.png) !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  transform: scaleX(-1) !important;
  z-index: 9999 !important;
  pointer-events: none !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
}

